<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import PhoneModelMultiSelect from '@/components/PhoneModelMultiSelect/index.vue'
import SupplierColorPanel from './SupplierColorPanel.vue'
import {newRequestId} from '@/api/modules/partner'
import {previewSupplierRange,saveSupplierRanges,supplierColors,supplierRanges,updateSupplierShortCode,type SupplierColor,type SupplierRange,type SupplierRangeMember,type SupplierRangePreview,type SupplierScopeMetadata} from '@/api/modules/supplierRanges'
import {partnerError} from '@/utils/partnerError'
import {parseSelectionTsv} from '@/utils/partnerSelections'
const props=defineProps<{supplierCode:string;canWrite:boolean;initialTab?:'model'|'color'|'colors'}>()
const emit=defineEmits<{'metadata-saved':[supplierCode:string,metadata:SupplierScopeMetadata]}>()
const tab=ref<'model'|'color'|'colors'>(props.initialTab||'model'),keyword=ref(''),page=ref(1),total=ref(0),rows=ref<SupplierRange[]>([]),meta=ref<SupplierScopeMetadata>(),shortCode=ref(''),error=ref(''),busy=ref(false),allowed=ref(false)
const dialog=ref(false),reason=ref(''),raw=ref(''),preview=ref<SupplierRangePreview>(),phoneIds=ref<number[]>([]),colorIds=ref<number[]>([]),colorOptions=ref<SupplierColor[]>([]),colorPage=ref(1),colorTotal=ref(0),colorKeyword=ref('')
const form=reactive<Partial<SupplierRange>>({}),canEdit=computed(()=>props.canWrite&&allowed.value)
const stateName=(value:string)=>({active:'可用',draft:'待核实',inactive:'已停用'} as Record<string,string>)[value]||value
let sequence=0
async function load(){const current=++sequence;busy.value=true;error.value='';try{const data=await supplierRanges(props.supplierCode,{page:page.value,size:20,keyword:keyword.value,type:tab.value==='color'?'color':'model'});if(current===sequence){rows.value=data.content;total.value=data.totalElements;meta.value=data.supplier;shortCode.value=data.supplier.shortCode||'';allowed.value=data.canWrite}}catch(e){if(current===sequence)error.value=partnerError(e)}finally{if(current===sequence)busy.value=false}}
watch(()=>[props.supplierCode,tab.value],()=>{page.value=1;void load()},{immediate:true})
async function saveCode(){if(!meta.value||!canEdit.value||busy.value)return;const code=props.supplierCode,value=shortCode.value.trim().toUpperCase(),unchanged=value===(meta.value.shortCode||'').trim().toUpperCase();error.value='';if(value&&!unchanged&&!/^[A-Z0-9][A-Z0-9-]*$/.test(value)){error.value='简码只用大写英文字母、数字和半角 -，不能含中文、空格或下划线。';return}busy.value=true;try{const saved=await updateSupplierShortCode(code,{version:meta.value.version,shortCode:value,reason:'国内工程维护供应商简码',requestId:newRequestId()});emit('metadata-saved',code,saved);if(props.supplierCode===code){meta.value=saved;shortCode.value=saved.shortCode||''}ElMessage.success(uiText('简码已保存；已有编号和历史标签不变'))}catch(e){if(props.supplierCode===code)error.value=partnerError(e)}finally{if(props.supplierCode===code)busy.value=false}}
async function loadColors(){try{const data=await supplierColors(props.supplierCode,{page:colorPage.value,size:20,keyword:colorKeyword.value});colorOptions.value=data.content;colorTotal.value=data.totalElements}catch(e){error.value=partnerError(e)}}
function openRange(row?:SupplierRange){Object.keys(form).forEach(key=>delete (form as Record<string,unknown>)[key]);Object.assign(form,row?JSON.parse(JSON.stringify(row)):{id:0,version:0,type:tab.value==='color'?'color':'model',name:'',aliases:[],members:[],status:'draft',styleKey:'',configKey:'',notes:''});phoneIds.value=form.type==='model'?(form.members||[]).map(item=>item.id):[];colorIds.value=form.type==='color'?(form.members||[]).map(item=>item.id):[];raw.value=(form.pendingValues||[]).map(value=>typeof value==='string'?value:String((value as Record<string,unknown>).raw||'')).join('\n');reason.value='';preview.value=undefined;dialog.value=true;if(form.type==='color')void loadColors()}
function toggleColor(id:number,checked:boolean){colorIds.value=checked?[...new Set([...colorIds.value,id])]:colorIds.value.filter(value=>value!==id);preview.value=undefined}
async function checkRange(){busy.value=true;error.value='';try{preview.value=await previewSupplierRange(props.supplierCode,{type:form.type!,values:raw.value.split(/\r?\n|\t/).map(value=>value.trim()).filter(Boolean),memberIds:form.type==='model'?phoneIds.value:colorIds.value,styleKey:form.styleKey,configKey:form.configKey})}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function resolveMember(index:number,id:number){if(!preview.value)return;const row=preview.value.rows[index],member=row.candidates.find(item=>item.id===id);if(!member)return;row.member=member;row.state='matched';preview.value.members=[...new Map(preview.value.rows.filter(item=>item.member).map(item=>[item.member!.id,item.member!])).values(),...(form.type==='model'?phoneIds.value:colorIds.value).filter(value=>!preview.value!.rows.some(item=>item.member?.id===value)).map(value=>({id:value}))];preview.value.unresolvedCount=preview.value.rows.filter(item=>item.state==='missing'||item.state==='ambiguous').length}
async function saveRange(){if(!preview.value||!form.name?.trim()||!reason.value.trim())return;busy.value=true;error.value='';try{await saveSupplierRanges(props.supplierCode,{requestId:newRequestId(),reason:reason.value,items:[{...form,members:preview.value.members,pendingValues:preview.value.rows.filter(row=>row.state==='missing'||row.state==='ambiguous'),status:preview.value.unresolvedCount?'draft':form.status}]});dialog.value=false;ElMessage.success(uiText('范围新版本已保存；既有选品依据不变'));await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
async function readRangeList(file:File){try{const text=await file.text(),cells=parseSelectionTsv(text.replace(/^\uFEFF/,''),file.name.toLowerCase().endsWith('.csv')?',':'\t');if(cells.some(row=>row.slice(1).some(value=>value.trim())))throw new Error('型号／颜色范围清单请只放一列名称或编码；多列资料请直接复制需要的一列。');raw.value=cells.map(row=>row[0]).join('\n');preview.value=undefined}catch(e){error.value=partnerError(e)}return false}
const memberName=(member:SupplierRangeMember)=>String(member.name||member.modelName||member.raw||member.code||`#${member.id}`)
</script>
<template><section class="supplier-ranges" v-loading="busy"><header><h3>{{ uiText("供应商资料设置") }}</h3><span class="muted">{{ uiText("引用范围不等于全部组合可供") }}</span></header><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="range-toolbar"><label>{{ uiText("供应商简码") }}</label><el-input v-model="shortCode" :disabled="!canEdit" :placeholder='uiText("如 XD、XDT、XD2")' :aria-label='uiText("供应商简码")'/><el-button v-if="canEdit" :disabled="busy" @click="saveCode">{{ uiText("保存简码") }}</el-button></div><p class="muted">{{ uiText("全系统唯一，熊大保留 XD；建议 2—4 位，不固定三位。可用大写英文、数字和半角 -，旧简码与历史标签保留追溯。") }}</p>
 <el-radio-group v-model="tab" size="small"><el-radio-button value="model">{{ uiText("型号范围") }}</el-radio-button><el-radio-button value="color">{{ uiText("颜色范围") }}</el-radio-button><el-radio-button value="colors">{{ uiText("供应商颜色") }}</el-radio-button></el-radio-group>
 <SupplierColorPanel v-if="tab==='colors'" :supplier-code="supplierCode" :can-write="canWrite"/>
 <template v-else><div class="range-toolbar"><el-input v-model="keyword" clearable :placeholder='uiText("名称／编码／别名")' @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">{{ uiText("查询") }}</el-button><el-button v-if="canEdit" type="primary" @click="openRange()">{{ uiText("新增范围") }}</el-button></div><div class="range-list"><article v-for="row in rows" :key="row.id"><div><strong>{{row.name}}</strong><p>{{row.code}} · {{stateName(row.status)}} · V{{row.version}}</p><p>{{row.members.length}}{{ uiText(" 个明确成员 ") }}<span v-if="row.aliases.length">{{ uiText("· 别名 ") }}{{row.aliases.join('、')}}</span></p></div><div class="range-preview"><span>{{row.members.slice(0,3).map(memberName).join('、')}}</span><details v-if="row.members.length>3"><summary>{{ uiText("查看全部成员") }}</summary>{{row.members.map(memberName).join('、')}}</details></div><el-button v-if="canEdit" link type="primary" @click="openRange(row)">{{ uiText("批量增补／移除") }}</el-button></article><el-empty v-if="!rows.length&&!busy" :description='uiText("暂无记录；可直接整列粘贴批量维护")'/></div><el-pagination v-model:current-page="page" :total="total" :page-size="20" :pager-count="5" layout="total,prev,pager,next" @current-change="load"/></template>
 <el-dialog v-model="dialog" :title="form.id?uiText('维护范围新版本'):uiText('新增范围')" width="min(900px,96vw)" append-to-body :close-on-click-modal="false"><el-form label-position="top" size="small"><div class="range-fields"><el-form-item :label='uiText("范围名称 *")'><el-input v-model="form.name"/></el-form-item><el-form-item :label='uiText("别名（用逗号分隔）")'><el-input :model-value="form.aliases?.join('，')" @update:model-value="form.aliases=String($event).split(/[，,]/).map(v=>v.trim()).filter(Boolean)"/></el-form-item><el-form-item :label='uiText("仅适用款式（可空）")'><el-input v-model="form.styleKey"/></el-form-item><el-form-item :label='uiText("仅适用配置（可空）")'><el-input v-model="form.configKey"/></el-form-item></div><el-form-item v-if="form.type==='model'" :label='uiText("从现有手机资料批量选择")'><PhoneModelMultiSelect v-model="phoneIds" @update:model-value="preview=undefined"/></el-form-item><el-form-item v-else :label='uiText("从本供应商颜色批量选择")'><div class="color-choices"><div class="range-toolbar"><el-input v-model="colorKeyword" :placeholder='uiText("搜索本供应商颜色")' @keyup.enter="colorPage=1;loadColors()"/><el-button @click="colorPage=1;loadColors()">{{ uiText("查询") }}</el-button></div><el-checkbox v-for="color in colorOptions" :key="color.id" :model-value="colorIds.includes(color.id)" @change="toggleColor(color.id,Boolean($event))">{{color.name}}<template v-if="color.supplierColorCode"> · {{color.supplierColorCode}}</template></el-checkbox><el-pagination v-model:current-page="colorPage" :total="colorTotal" :page-size="20" layout="prev,pager,next" @current-change="loadColors"/><p>{{ uiText("已选 ") }}{{colorIds.length}}{{ uiText(" 项，跨页保留。") }}</p></div></el-form-item><el-form-item :label='uiText("或粘贴一列名称／已有编码（不自动新增手机及标准颜色）")'><el-input v-model="raw" type="textarea" :rows="4" @input="preview=undefined"/><el-upload :show-file-list="false" accept=".csv,.tsv,.txt" :before-upload="readRangeList"><el-button link>{{ uiText("导入文本清单（Excel也可整列复制粘贴）") }}</el-button></el-upload></el-form-item><el-button :disabled="busy" @click="checkRange">{{ uiText("核对成员与变更差异") }}</el-button><section v-if="preview" class="range-diff"><p>{{ uiText("拟保存 ") }}{{preview.members.length}}{{ uiText(" 个明确成员 · ") }}{{preview.unresolvedCount}}{{ uiText(" 项待核实；未核实只能存草稿。") }}</p><p v-if="form.id">{{ uiText("较旧版新增 ") }}{{preview.members.filter(m=>!form.members?.some(o=>o.id===m.id)).length}}{{ uiText(" 项，移除 ") }}{{form.members?.filter(m=>!preview?.members.some(n=>n.id===m.id)).length}}{{ uiText(" 项。移除只影响新版本，不改变历史依据。") }}</p><article v-for="(item,index) in preview.rows" :key="index"><span>{{item.raw}} · {{({matched:uiText('已匹配'),duplicate:uiText('重复'),ambiguous:uiText('多义待选'),missing:uiText('未找到')})[item.state]}}</span><el-select v-if="item.state==='ambiguous'" :placeholder='uiText("明确选择已有成员")' @update:model-value="resolveMember(index,Number($event))"><el-option v-for="candidate in item.candidates" :key="candidate.id" :value="candidate.id" :label="memberName(candidate)"/></el-select></article></section><el-form-item :label='uiText("状态")'><el-select v-model="form.status"><el-option :label='uiText("待核实草稿")' value="draft"/><el-option :label='uiText("可用（成员全部核实）")' value="active"/><el-option :label='uiText("停用（保留历史）")' value="inactive"/></el-select></el-form-item><el-form-item :label='uiText("本次维护原因 *")'><el-input v-model="reason" type="textarea" autosize/></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{ uiText("取消") }}</el-button><el-button type="primary" :disabled="!preview||!form.name?.trim()||!reason.trim()||busy" @click="saveRange">{{ uiText("保存新版本") }}</el-button></template></el-dialog>
</section></template>
<style scoped>.supplier-ranges{min-width:0;container-type:inline-size}.supplier-ranges header,.range-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0}.supplier-ranges h3{margin:0;font-size:14px}.muted,.range-list p{font-size:12px;color:var(--el-text-color-secondary)}.range-toolbar>.el-input{flex:1;min-width:130px}.range-toolbar>label{font-size:12px}.range-list article{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr) auto;gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid var(--el-border-color-lighter)}.range-list article>*{min-width:0;overflow-wrap:anywhere}.range-list p{margin:3px 0}.range-preview{font-size:12px;line-height:1.7}.range-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.range-diff{max-height:240px;overflow:auto;font-size:12px;margin:10px 0}.range-diff article{display:flex;gap:8px;padding:4px 0;align-items:center}.color-choices{width:100%;min-width:0}.color-choices .el-checkbox{height:auto;min-height:28px}.supplier-ranges :deep(.el-pagination){flex-wrap:wrap;margin-top:7px}.supplier-ranges :deep(.el-button){white-space:normal;height:auto;line-height:1.6;min-height:26px}.supplier-ranges :deep(.el-button+.el-button){margin-left:0}@container(max-width:650px){.range-list article{grid-template-columns:minmax(0,1fr) auto}.range-preview{grid-column:1/-1}.range-fields{grid-template-columns:1fr}}</style>
